// iOS에서는 clientId를 명시적으로 지정해야 함
final GoogleSignIn _googleSignIn = GoogleSignIn(
  // Google Cloud Console의 iOS 클라이언트 ID
  clientId: 'YOUR_IOS_CLIENT_ID.apps.googleusercontent.com',
  scopes: ['email', 'profile'],
);

import 'package:google_sign_in/google_sign_in.dart';

class GoogleAuthService {
  // GoogleSignIn 인스턴스 (싱글톤으로 사용 권장)
  static final GoogleSignIn _googleSignIn = GoogleSignIn(
    scopes: [
      'email',
      'profile',
    ],
  );

  // 현재 로그인된 사용자
  static GoogleSignInAccount? get currentUser => _googleSignIn.currentUser;

  // 로그인 상태 스트림
  static Stream<GoogleSignInAccount?> get onCurrentUserChanged {
    return _googleSignIn.onCurrentUserChanged;
  }

  // 로그인
  static Future<GoogleSignInAccount?> signIn() async {
    try {
      final account = await _googleSignIn.signIn();
      if (account != null) {
        print('로그인 성공: ${account.displayName}');
        print('이메일: ${account.email}');
        print('프로필 사진: ${account.photoUrl}');
      }
      return account;
    } catch (error) {
      print('로그인 실패: $error');
      return null;
    }
  }

  // 자동 로그인 (이전 세션 복원)
  static Future<GoogleSignInAccount?> signInSilently() async {
    try {
      return await _googleSignIn.signInSilently();
    } catch (error) {
      print('자동 로그인 실패: $error');
      return null;
    }
  }

  // 로그아웃
  static Future<void> signOut() async {
    await _googleSignIn.signOut();
    print('로그아웃 완료');
  }

  // 연결 해제 (앱 권한 완전 제거)
  static Future<void> disconnect() async {
    await _googleSignIn.disconnect();
    print('Google 계정 연결 해제');
  }

  // 액세스 토큰 획득 (Google API 호출용)
  static Future<String?> getAccessToken() async {
    final account = _googleSignIn.currentUser;
    if (account == null) return null;

    final auth = await account.authentication;
    return auth.accessToken;
  }

  // ID 토큰 획득 (백엔드 인증용)
  static Future<String?> getIdToken() async {
    final account = _googleSignIn.currentUser;
    if (account == null) return null;

    final auth = await account.authentication;
    return auth.idToken;
  }
}

import 'package:flutter/material.dart';
import 'package:google_sign_in/google_sign_in.dart';
import '../services/google_auth_service.dart';

class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});

  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
  GoogleSignInAccount? _currentUser;
  bool _isLoading = false;

  @override
  void initState() {
    super.initState();
    // 로그인 상태 변경 리스너
    GoogleAuthService.onCurrentUserChanged.listen((account) {
      setState(() => _currentUser = account);
    });
    // 앱 시작 시 자동 로그인 시도
    _tryAutoSignIn();
  }

  Future<void> _tryAutoSignIn() async {
    setState(() => _isLoading = true);
    final account = await GoogleAuthService.signInSilently();
    setState(() {
      _currentUser = account;
      _isLoading = false;
    });
  }

  Future<void> _handleSignIn() async {
    setState(() => _isLoading = true);
    final account = await GoogleAuthService.signIn();
    setState(() {
      _currentUser = account;
      _isLoading = false;
    });
  }

  Future<void> _handleSignOut() async {
    await GoogleAuthService.signOut();
    setState(() => _currentUser = null);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Google 로그인')),
      body: Center(
        child: _isLoading
            ? const CircularProgressIndicator()
            : _currentUser != null
                ? _buildUserInfo()
                : _buildSignInButton(),
      ),
    );
  }

  Widget _buildSignInButton() {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        const Text(
          'Google 계정으로 로그인하세요',
          style: TextStyle(fontSize: 18),
        ),
        const SizedBox(height: 24),
        // 기본 스타일 버튼
        ElevatedButton.icon(
          onPressed: _handleSignIn,
          icon: Image.network(
            'https://developers.google.com/identity/images/g-logo.png',
            height: 24,
          ),
          label: const Text('Google로 로그인'),
          style: ElevatedButton.styleFrom(
            backgroundColor: Colors.white,
            foregroundColor: Colors.black87,
            padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
          ),
        ),
        const SizedBox(height: 16),
        // 커스텀 스타일 버튼
        _buildGoogleSignInButton(),
      ],
    );
  }

  Widget _buildGoogleSignInButton() {
    return InkWell(
      onTap: _handleSignIn,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
        decoration: BoxDecoration(
          border: Border.all(color: Colors.grey.shade300),
          borderRadius: BorderRadius.circular(4),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Image.network(
              'https://developers.google.com/identity/images/g-logo.png',
              height: 20,
            ),
            const SizedBox(width: 12),
            const Text(
              'Sign in with Google',
              style: TextStyle(
                fontSize: 14,
                fontWeight: FontWeight.w500,
                color: Colors.black54,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildUserInfo() {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        // 프로필 사진
        if (_currentUser!.photoUrl != null)
          CircleAvatar(
            radius: 50,
            backgroundImage: NetworkImage(_currentUser!.photoUrl!),
          )
        else
          CircleAvatar(
            radius: 50,
            child: Text(
              _currentUser!.displayName?[0] ?? '?',
              style: const TextStyle(fontSize: 32),
            ),
          ),
        const SizedBox(height: 16),

        // 사용자 이름
        Text(
          _currentUser!.displayName ?? '이름 없음',
          style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold),
        ),
        const SizedBox(height: 8),

        // 이메일
        Text(
          _currentUser!.email,
          style: TextStyle(fontSize: 16, color: Colors.grey[600]),
        ),
        const SizedBox(height: 24),

        // 로그아웃 버튼
        ElevatedButton(
          onPressed: _handleSignOut,
          child: const Text('로그아웃'),
        ),
      ],
    );
  }
}

import 'package:firebase_auth/firebase_auth.dart';
import 'package:google_sign_in/google_sign_in.dart';

class FirebaseGoogleAuth {
  static final FirebaseAuth _auth = FirebaseAuth.instance;
  static final GoogleSignIn _googleSignIn = GoogleSignIn();

  // 현재 Firebase 사용자
  static User? get currentUser => _auth.currentUser;

  // 인증 상태 스트림
  static Stream<User?> get authStateChanges => _auth.authStateChanges();

  // Google 로그인 + Firebase 연동
  static Future<UserCredential?> signInWithGoogle() async {
    try {
      // 1. Google 로그인
      final GoogleSignInAccount? googleUser = await _googleSignIn.signIn();
      if (googleUser == null) {
        // 사용자가 로그인 취소
        return null;
      }

      // 2. 인증 정보 획득
      final GoogleSignInAuthentication googleAuth = 
          await googleUser.authentication;

      // 3. Firebase 자격 증명 생성
      final AuthCredential credential = GoogleAuthProvider.credential(
        accessToken: googleAuth.accessToken,
        idToken: googleAuth.idToken,
      );

      // 4. Firebase에 로그인
      final UserCredential userCredential = 
          await _auth.signInWithCredential(credential);

      print('Firebase 로그인 성공: ${userCredential.user?.email}');
      return userCredential;
    } on FirebaseAuthException catch (e) {
      print('Firebase 인증 오류: ${e.code} - ${e.message}');
      return null;
    } catch (e) {
      print('로그인 오류: $e');
      return null;
    }
  }

  // 로그아웃
  static Future<void> signOut() async {
    await Future.wait([
      _auth.signOut(),
      _googleSignIn.signOut(),
    ]);
  }

  // 계정 삭제
  static Future<void> deleteAccount() async {
    final user = _auth.currentUser;
    if (user != null) {
      // 재인증 필요할 수 있음
      await user.delete();
      await _googleSignIn.disconnect();
    }
  }

  // 다른 제공자와 계정 연결
  static Future<UserCredential?> linkWithGoogle() async {
    final googleUser = await _googleSignIn.signIn();
    if (googleUser == null) return null;

    final googleAuth = await googleUser.authentication;
    final credential = GoogleAuthProvider.credential(
      accessToken: googleAuth.accessToken,
      idToken: googleAuth.idToken,
    );

    return await _auth.currentUser?.linkWithCredential(credential);
  }
}

// 사용 예시 위젯
import 'package:flutter/material.dart';

class FirebaseGoogleLoginScreen extends StatelessWidget {
  const FirebaseGoogleLoginScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<User?>(
      stream: FirebaseGoogleAuth.authStateChanges,
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting) {
          return const Center(child: CircularProgressIndicator());
        }

        final user = snapshot.data;

        if (user != null) {
          // 로그인된 상태
          return Scaffold(
            body: Center(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Text('환영합니다, ${user.displayName}!'),
                  Text('UID: ${user.uid}'),
                  const SizedBox(height: 16),
                  ElevatedButton(
                    onPressed: FirebaseGoogleAuth.signOut,
                    child: const Text('로그아웃'),
                  ),
                ],
              ),
            ),
          );
        }

        // 로그아웃된 상태
        return Scaffold(
          body: Center(
            child: ElevatedButton(
              onPressed: FirebaseGoogleAuth.signInWithGoogle,
              child: const Text('Google로 로그인'),
            ),
          ),
        );
      },
    );
  }
}

